// Phase 18G — classify news type while preserving canonical envelope.
// Reads upstream $json (envelope from FF90-01). Sets news_type.
// In production: only classifies when editorial content is already
// populated (via admin UI); when missing AND no test_marker, returns
// pipeline_status=held_for_content and the chain short-circuits.
const up = $json;
const src = up.source_url ? up : (up.raw || {});  // tolerate upstream shape
const optMeta = up.optional_metadata || src.optional_metadata || {};
const testMarker = optMeta.phase === '18f-b' && optMeta.test_content;
const testContent = testMarker ? optMeta.test_content : null;

// News type enum: RESULT | PREVIEW | ANALYSIS | TRANSFER | BREAKING
// (plus 'test' for Phase 18F-B synthetic fixtures).
// Determine canonical editorial fields. Production: must already be
// present on the editorial_item (admin UI pre-populated). Test fixture:
// pull from optional_metadata.test_content.
const fields = {
  news_type: src.news_type || up.news_type || (testContent ? testContent.news_type : null) || 'RESULT',
  title_th: src.title_th || up.title_th || (testContent ? testContent.title_th : null) || null,
  body_th: src.body_th || up.body_th || (testContent ? testContent.body_th : null) || null,
  excerpt_th: src.excerpt_th || up.excerpt_th || (testContent ? testContent.excerpt_th : null) || null,
  slug: src.slug || up.slug || (testContent ? testContent.slug : null) || null,
};

// Fail-closed: in production (no test_marker) if any required editorial
// field is missing, hold for content.
const hasAllContent = !!(fields.title_th && fields.body_th);
const failClosed = !testMarker && !hasAllContent;

return [{
  json: {
    ...up,
    ...fields,
    pipeline_stage: 'editorial_factory',
    pipeline_status: failClosed ? 'held_for_content' : 'accepted',
    metadata: { ...(up.metadata || {}), test_marker: !!testMarker },
  },
}];

// Build the LLM article prompt (Thai). NEVER invents quotes, statistics,
// transfers, or injuries. Notes the news_type for downstream template routing.
const newsType = $json.news_type;
const src = $json.source || {};
const titleHint = src.source_title || '';
const text = src.source_text || '';
const prompt = [
  'You are writing a Thai football news article for FF90.online.',
  `News type: ${newsType}.`,
  'Hard rules:',
  ' - natural Thai, football-news style',
  ' - clear paragraphs (no giant wall of text)',
  ' - no invented quote',
  ' - no invented statistic',
  ' - no fabricated transfer or injury information',
  ' - no long verbatim copying of source text',
  ' - 2,000-3,500 Thai characters when source material supports it',
  '   (NEVER pad with fabricated content to reach a length target)',
  '',
  `Source title: ${titleHint}`,
  `Publisher: ${src.publisher || '(unknown)'}`,
  `Published at: ${src.published_at || '(unknown)'}`,
  `Competition: ${src.competition || '(unknown)'}`,
  `Teams: ${(src.teams || []).join(', ') || '(unknown)'}`,
  `People: ${(src.people || []).join(', ') || '(unknown)'}`,
  '',
  'Source text:',
  text.slice(0, 8000),
].join('\n');
return [{ json: { ...$json, article_prompt: prompt } }];

// Phase 18G — terminal promote. Re-emits canonical envelope with
// pipeline_status chosen upstream. Always preserves run_id, editorial_item_id,
// source_*, news_type, title_th, body_th, excerpt_th, slug.
const up = $json;
// Pull upstream editorial fields from the Classify news type output
// (the most-recent canonical envelope in the chain).
const classified = $('Classify news type').item.json || {};
const merged = {
  ...classified,
  ...up,
  run_id: classified.run_id || up.run_id || null,
  editorial_item_id: classified.editorial_item_id || up.editorial_item_id || null,
  source_id: classified.source_id ?? up.source_id ?? null,
  source_url: classified.source_url ?? up.source_url ?? null,
  source_title: classified.source_title ?? up.source_title ?? null,
  publisher: classified.publisher ?? up.publisher ?? null,
  published_at: classified.published_at ?? up.published_at ?? null,
  source_type: classified.source_type ?? up.source_type ?? null,
  source_text: classified.source_text ?? up.source_text ?? null,
  news_type: classified.news_type ?? up.news_type ?? null,
  title_th: classified.title_th ?? up.title_th ?? null,
  body_th: classified.body_th ?? up.body_th ?? null,
  excerpt_th: classified.excerpt_th ?? up.excerpt_th ?? null,
  slug: classified.slug ?? up.slug ?? null,
  pipeline_stage: 'editorial_factory',
  pipeline_status: classified.pipeline_status || 'accepted',
};
return [{ json: merged }];
